javascript:
frappe.query_reports["Case Diary"] = {
	"filters": [
	    {
	        "fieldname":"from_date",
			"label": __("From Date"),
			"fieldtype": "Date",
			"reqd": 1,
			"default": "Today"
	    },
	    {
	        "fieldname":"to_date",
			"label": __("To Date"),
			"fieldtype": "Date",
			"reqd": 1,
			"default": "Today"
	    },
        {
			"fieldname":"service",
			"label": __("Service"),
			"fieldtype": "MultiSelectList",
			"reqd": 1,
			get_data: function(txt) {
				return frappe.db.get_link_options('Service', txt, {service_type: "Cases"});
			}
		},
		{
			"fieldname":"case_stage",
			"label": __("Case Stage"),
			"fieldtype": "MultiSelectList",
			"reqd": 1,
			get_data: function(txt) {
				return frappe.db.get_link_options('Case Stage', txt);
			}
		}
	]
};
